import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    idx = 1

    dice = []
    sizes = []

    for _ in range(N):
        K = int(data[idx])
        idx += 1
        sizes.append(K)

        freq = {}
        for _ in range(K):
            a = int(data[idx])
            idx += 1
            freq[a] = freq.get(a, 0) + 1
        dice.append(freq)

    ans = 0.0

    for i in range(N):
        for j in range(i + 1, N):
            if len(dice[i]) <= len(dice[j]):
                small, large = dice[i], dice[j]
            else:
                small, large = dice[j], dice[i]

            match = 0
            for value, count in small.items():
                match += count * large.get(value, 0)

            ans = max(ans, match / (sizes[i] * sizes[j]))

    print(ans)

if __name__ == "__main__":
    solve()
